          {
            "selected": true
          }
        ],
        "items": {
          "type": "object",
          "description": "单条勾选状态",
          "properties": {
            "selected": {
              "type": "boolean",
              "description": "该日程是否已勾选",
              "sampleValue": false
            }
          }
        }
      }
    },
    "music": {
      "title": {
        "type": "string",
        "description": "音乐歌单入口标题",
        "sampleValue": "音乐歌单"
      },
      "subtitle": {
        "type": "string",
        "description": "整理照片时听歌的入口说明",
        "sampleValue": "边听边整理"
      },
      "actionLabel": {
        "type": "string",
        "description": "跳转音乐应用的动作文案",
        "sampleValue": "打开歌单"
      }
    },
    "status": {
      "message": {
        "type": "string",
        "description": "相册备份任务取消后的红色告警文案",
        "sampleValue": "备份任务已取消，请重试"
      }
    }
  },
  "assetCandidates": []
}

